var a=`0458-imam-bay-ld`;var i=`world-0458`;var n=`TR`;var o=`western-asia`;var r=4;var l=77;var s={en:`İmam Bayıldı`,ua:`Імам баялди`};var g={en:`A traditional dish from Türkiye, centered on eggplant, yellow onion, garlic, tomato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Туреччина. Основні складники: баклажан, жовта цибуля, часник, помідор. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Cut the vegetables evenly and roast at 200°C for about 22 minutes until tender and lightly charred.`,ua:`Наріжте овочі рівномірно та запікайте при 200°C приблизно 22 хвилин до м’якості й легкої підпеченої скоринки.`,t:[`roasting`],m:22,i:[[`eggplant`,700,`g`],[`extra-virgin-olive-oil`,70,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`yellow-onion`,240,`g`],[`garlic`,4,`clove`],[`tomato`,480,`g`],[`extra-virgin-olive-oil`,40,`ml`]]},{en:`Hollow or prepare the vegetables, then fill with the prepared mixture without packing too tightly.`,ua:`Підготуйте овочі, за потреби вийміть серцевину, і наповніть начинкою, не утрамбовуючи надто щільно.`,t:[`stuffing-vegetables`],m:9,i:[]},{en:`Place the stuffed eggplants in a covered casserole with a little water and sugar and braise until silky, then cool to serve at room temperature.`,ua:`Помістіть начинені баклажани в закриту форму з невеликою кількістю води та цукру і тушкуйте до ніжності, потім остудіть до кімнатної температури.`,t:[`braising`],m:35,i:[[`water`,130,`ml`],[`white-granulated-sugar`,10,`g`],[`parsley`,25,`g`]]}];var d={slug:a,id:i,country:`TR`,region:o,servings:4,minutes:77,title:s,text:g,steps:u};export{n as country,d as default,i as id,l as minutes,o as region,r as servings,a as slug,u as steps,g as text,s as title};